/**
 * What the pages derive from `parser-scores.ts`: shares, the date, and which
 * frameworks no score covers yet.
 *
 * `parser-scores.ts` is GENERATED by `pnpm export:parser-scores` in the Lens
 * repo, from a run of the parser itself, and carries counts only. Every
 * percentage on the site is worked out here from those counts, so no page types
 * a score, and a regenerated file moves every figure that depends on it.
 */
import { PARSER_SCORES, type LeafTotals } from './parser-scores';
import { DEEP_FRAMEWORKS } from './frameworks';

export const SCORES = PARSER_SCORES;
const real = PARSER_SCORES.realProjects;
const fixtures = PARSER_SCORES.fixtures;

/**
 * `98.1%`. One decimal place. A shortfall never rounds up to 100%, and a share
 * above nothing never rounds down to 0%: either would be a claim the count denies.
 */
export function share(n: number, d: number): string {
  if (d === 0) return 'n/a';
  let pct = Math.round((n / d) * 1000) / 10;
  if (n < d && pct >= 100) pct = 99.9;
  if (n > 0 && pct <= 0) pct = 0.1;
  return `${pct.toFixed(1)}%`;
}

/** `2,337`. */
export const count = (n: number): string => n.toLocaleString('en-US');

const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
];

/** `2026-10-26` → `26 October 2026`, without a time zone to shift the day. */
export function longDate(iso: string): string {
  const [y, m, d] = iso.split('-').map(Number);
  return `${d} ${MONTHS[m - 1]} ${y}`;
}

/** Every field an answer key documents on a matched endpoint, whatever the code side had. */
export const documentedFields = (l: LeafTotals): number => l.comparable + l.dynamic + l.missing;

/** Projects marked against an answer key made from their own code, and what contradicted it. */
export const ownKeyProjects = real.answerKeys.own + real.answerKeys['hand-verified'];
export const ownKeyContradictions = real.codeWrong.own + real.codeWrong['hand-verified'];

/** Frameworks the fixture suite measures and no real project does yet. */
export const fixtureOnlyFrameworks = fixtures.frameworks.filter((f) => !real.frameworks.includes(f));

/**
 * Frameworks the site lists as read at full depth that no score covers. A label
 * such as `ASP.NET Core` covers `ASP.NET Core MVC` and `ASP.NET Core minimal APIs`.
 */
export const unmeasuredFrameworks = (() => {
  const measured = [...real.frameworks, ...fixtures.frameworks];
  return DEEP_FRAMEWORKS.flatMap((row) => row.frameworks).filter(
    (name) => !measured.some((m) => name === m || name.startsWith(`${m} `)),
  );
})();
